17	package org.springframework.samples.petclinic.rest.controller.v1;
18	
19	import java.time.LocalDate;
20	import java.util.ArrayList;
21	import java.util.Collection;
22	import java.util.List;
23	
24	import org.slf4j.Logger;
25	import org.slf4j.LoggerFactory;
26	import org.springframework.http.HttpHeaders;
27	import org.springframework.http.HttpStatus;
28	import org.springframework.http.ResponseEntity;
29	import org.springframework.samples.petclinic.mapper.OwnerMapper;
30	import org.springframework.samples.petclinic.mapper.PetMapper;
31	import org.springframework.samples.petclinic.mapper.VisitMapper;
32	import org.springframework.samples.petclinic.model.Owner;
33	import org.springframework.samples.petclinic.model.Pet;
34	import org.springframework.samples.petclinic.model.Visit;
35	import org.springframework.samples.petclinic.rest.advice.CityCapacityExceededException;
36	import org.springframework.samples.petclinic.rest.advice.DailyOwnerLimitExceededException;
37	import org.springframework.samples.petclinic.rest.advice.DuplicateIdentityException;
38	import org.springframework.samples.petclinic.rest.advice.InvalidFieldsException;
39	import org.springframework.samples.petclinic.rest.advice.RequiredFieldsMissingException;
40	import org.springframework.samples.petclinic.rest.api.OwnersApi;
41	import org.springframework.samples.petclinic.rest.dto.OwnerDto;
42	import org.springframework.samples.petclinic.rest.dto.OwnerFieldsDto;
43	import org.springframework.samples.petclinic.rest.dto.PetDto;
44	import org.springframework.samples.petclinic.rest.dto.PetFieldsDto;
45	import org.springframework.samples.petclinic.rest.dto.VisitDto;
46	import org.springframework.samples.petclinic.rest.dto.VisitFieldsDto;
47	import org.springframework.samples.petclinic.service.ClinicService;
48	import org.springframework.security.access.prepost.PreAuthorize;
49	import org.springframework.web.bind.annotation.CrossOrigin;
50	import org.springframework.web.bind.annotation.RequestMapping;
51	import org.springframework.web.bind.annotation.RestController;
52	import org.springframework.web.util.UriComponentsBuilder;
53	
54	import jakarta.transaction.Transactional;
55	
56	/**
57	 * @author Vitaliy Fedoriv
58	 */
59	
60	@RestController
61	@CrossOrigin(exposedHeaders = "errors, content-type")
62	@RequestMapping("/api")
63	public class OwnerRestControllerV1 implements OwnersApi {
64	
65	    private static final Logger AUDIT = LoggerFactory.getLogger("AUDIT");
66	
67	    private final ClinicService clinicService;
68	
69	    private final OwnerMapper ownerMapper;
70	
71	    private final PetMapper petMapper;
72	
73	    private final VisitMapper visitMapper;
74	
75	    public OwnerRestControllerV1(ClinicService clinicService,
76	                                 OwnerMapper ownerMapper,
77	                                 PetMapper petMapper,
78	                                 VisitMapper visitMapper) {
79	        this.clinicService = clinicService;
80	        this.ownerMapper = ownerMapper;
81	        this.petMapper = petMapper;
82	        this.visitMapper = visitMapper;
83	    }
84	
85	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
86	    @Override
87	    public ResponseEntity<List<OwnerDto>> listOwners(String lastName) {
88	        Collection<Owner> owners;
89	        if (lastName != null) {
90	            owners = this.clinicService.findOwnerByLastName(lastName);
91	        } else {
92	            owners = this.clinicService.findAllOwners();
93	        }
94	        if (owners.isEmpty()) {
95	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
96	        }
97	        return new ResponseEntity<>(ownerMapper.toOwnerDtoCollection(owners), HttpStatus.OK);
98	    }
99	
100	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
101	    @Override
102	    public ResponseEntity<OwnerDto> getOwner(Integer ownerId) {
103	        Owner owner = this.clinicService.findOwnerById(ownerId);
104	        if (owner == null) {
105	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
106	        }
107	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
108	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
109	        ownerDto.setBulkSignupWarning(bulkSignupWarning(owner.getRegistrationDate()));
110	        return new ResponseEntity<>(ownerDto, HttpStatus.OK);
111	    }
112	
113	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
114	    @Override
115	    public ResponseEntity<OwnerDto> addOwner(OwnerFieldsDto ownerFieldsDto) {
116	        LocalDate registrationDate = effectiveRegistrationDate(ownerFieldsDto);
117	        prepareNewOwner(ownerFieldsDto, registrationDate);
118	        HttpHeaders headers = new HttpHeaders();
119	        Owner owner = ownerMapper.toOwner(ownerFieldsDto);
120	        owner.setRegistrationDate(registrationDate);
121	        owner.setCustomerCode(customerCodeFor(owner));
122	        owner.setNamesakeCount(countNamesakes(owner.getFirstName(), owner.getLastName()));
123	        assignHousehold(owner);
124	        applyPossibleDuplicate(owner, ownerFieldsDto);
125	        this.clinicService.saveOwner(owner);
126	        owner.setHouseholdMemberCount(countHouseholdMembers(owner.getHouseholdId()));
127	        AUDIT.info("Owner created: id={} customerCode={} registrationDate={} membershipLevel={}",
128	            owner.getId(), owner.getCustomerCode(), owner.getRegistrationDate(),
129	            owner.getMembershipLevel());
130	        OwnerDto ownerDto = ownerMapper.toOwnerDto(owner);
131	        ownerDto.setBulkSignupWarning(bulkSignupWarning(registrationDate));
132	        headers.setLocation(UriComponentsBuilder.newInstance()
133	            .path("/api/owners/{id}").buildAndExpand(owner.getId()).toUri());
134	        return new ResponseEntity<>(ownerDto, headers, HttpStatus.CREATED);
135	    }
136	
137	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
138	    @Override
139	    public ResponseEntity<OwnerDto> updateOwner(Integer ownerId, OwnerFieldsDto ownerFieldsDto) {
140	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
141	        if (currentOwner == null) {
142	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
143	        }
144	        currentOwner.setAddress(ownerFieldsDto.getAddress());
145	        currentOwner.setCity(ownerFieldsDto.getCity());
146	        currentOwner.setFirstName(ownerFieldsDto.getFirstName());
147	        currentOwner.setLastName(ownerFieldsDto.getLastName());
148	        currentOwner.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
149	        currentOwner.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
150	        this.clinicService.saveOwner(currentOwner);
151	        return new ResponseEntity<>(ownerMapper.toOwnerDto(currentOwner), HttpStatus.NO_CONTENT);
152	    }
153	
154	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
155	    @Transactional
156	    @Override
157	    public ResponseEntity<OwnerDto> deleteOwner(Integer ownerId) {
158	        Owner owner = this.clinicService.findOwnerById(ownerId);
159	        if (owner == null) {
160	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
161	        }
162	        this.clinicService.deleteOwner(owner);
163	        return new ResponseEntity<>(HttpStatus.NO_CONTENT);
164	    }
165	
166	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
167	    @Override
168	    public ResponseEntity<PetDto> addPetToOwner(Integer ownerId, PetFieldsDto petFieldsDto) {
169	        Owner owner = this.clinicService.findOwnerById(ownerId);
170	        if (owner == null) {
171	            return new ResponseEntity<>(HttpStatus.NOT_FOUND);
172	        }
173	        HttpHeaders headers = new HttpHeaders();
174	        Pet pet = petMapper.toPet(petFieldsDto);
175	        owner.setId(ownerId);
176	        pet.setOwner(owner);
177	        pet.getType().setName(null);
178	        this.clinicService.savePet(pet);
179	        PetDto petDto = petMapper.toPetDto(pet);
180	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/pets/{id}")
181	            .buildAndExpand(pet.getId()).toUri());
182	        return new ResponseEntity<>(petDto, headers, HttpStatus.CREATED);
183	    }
184	
185	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
186	    @Override
187	    public ResponseEntity<Void> updateOwnersPet(Integer ownerId, Integer petId, PetFieldsDto petFieldsDto) {
188	        Owner currentOwner = this.clinicService.findOwnerById(ownerId);
189	        if (currentOwner != null) {
190	            Pet currentPet = this.clinicService.findPetById(petId);
191	            if (currentPet != null) {
192	                currentPet.setBirthDate(petFieldsDto.getBirthDate());
193	                currentPet.setName(petFieldsDto.getName());
194	                currentPet.setType(petMapper.toPetType(petFieldsDto.getType()));
195	                this.clinicService.savePet(currentPet);
196	                return new ResponseEntity<>(HttpStatus.NO_CONTENT);
197	            }
198	        }
199	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
200	    }
201	
202	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
203	    @Override
204	    public ResponseEntity<VisitDto> addVisitToOwner(Integer ownerId, Integer petId, VisitFieldsDto visitFieldsDto) {
205	        HttpHeaders headers = new HttpHeaders();
206	        Visit visit = visitMapper.toVisit(visitFieldsDto);
207	        Pet pet = new Pet();
208	        pet.setId(petId);
209	        visit.setPet(pet);
210	        this.clinicService.saveVisit(visit);
211	        VisitDto visitDto = visitMapper.toVisitDto(visit);
212	        headers.setLocation(UriComponentsBuilder.newInstance().path("/api/visits/{id}")
213	            .buildAndExpand(visit.getId()).toUri());
214	        return new ResponseEntity<>(visitDto, headers, HttpStatus.CREATED);
215	    }
216	
217	
218	    @PreAuthorize("hasRole(@roles.OWNER_ADMIN)")
219	    @Override
220	    public ResponseEntity<PetDto> getOwnersPet(Integer ownerId, Integer petId) {
221	        Owner owner = this.clinicService.findOwnerById(ownerId);
222	        if (owner != null) {
223	            Pet pet = owner.getPet(petId);
224	            if (pet != null) {
225	                return new ResponseEntity<>(petMapper.toPetDto(pet), HttpStatus.OK);
226	            }
227	        }
228	        return new ResponseEntity<>(HttpStatus.NOT_FOUND);
229	    }
230	
231	    /**
232	     * Applies the intake rules a newly submitted owner must satisfy before it is persisted.
233	     * The address is normalized in place (so a required-field check that follows rejects an
234	     * address blank after normalization), the required fields are checked, the telephone and
235	     * email are normalized in place, and the resulting owner is rejected when its derived
236	     * identity key already belongs to another owner. Each rule
237	     * signals a violation by throwing, which the exception advice renders as the matching 4xx
238	     * response; when the method returns normally {@code ownerFieldsDto} is normalized and ready
239	     * to be mapped and saved.
240	     *
241	     * @param ownerFieldsDto the submitted owner fields, normalized in place
242	     */
243	    private void prepareNewOwner(OwnerFieldsDto ownerFieldsDto, LocalDate registrationDate) {
244	        ownerFieldsDto.setAddress(normalizeAddress(ownerFieldsDto.getAddress()));
245	        validateRequiredFields(ownerFieldsDto);
246	        ownerFieldsDto.setTelephone(normalizeTelephone(ownerFieldsDto.getTelephone()));
247	        ownerFieldsDto.setEmail(normalizeEmail(ownerFieldsDto.getEmail()));
248	        validatePostcode(ownerFieldsDto.getPostcode(), ownerFieldsDto.getCity());
249	        rejectDuplicateIdentity(ownerFieldsDto);
250	        rejectCityAtCapacity(ownerFieldsDto.getCity());
251	        rejectDailyLimitExceeded(registrationDate);
252	    }
253	
254	    /**
255	     * Determines the effective registration date for a newly submitted owner, adjusted so it always
256	     * falls on a business day. The date supplied on the request is used when present, otherwise the
257	     * server's current date is used. When that effective date lands on a Saturday or Sunday it is
258	     * rolled forward to the following Monday; a weekday is left unchanged. This single adjusted date
259	     * is what gets stored as {@code registrationDate} and is what every value derived from it (the
260	     * membership number's year segment, the per-day create limit) is computed against.
261	     *
262	     * A supplied registration date later than the server's current date is rejected with an
263	     * {@link InvalidFieldsException}, which the exception advice renders as a 400 Bad Request.
264	     *
265	     * @param ownerFieldsDto the submitted owner fields, which may carry a registration date
266	     * @return the effective registration date rolled forward to the next business day
267	     */
268	    private LocalDate effectiveRegistrationDate(OwnerFieldsDto ownerFieldsDto) {
269	        LocalDate supplied = ownerFieldsDto.getRegistrationDate();
270	        if (supplied != null && supplied.isAfter(LocalDate.now())) {
271	            throw new InvalidFieldsException(List.of("registrationDate"));
272	        }
273	        LocalDate effective = supplied != null ? supplied : LocalDate.now();
274	        return toBusinessDay(effective);
275	    }
276	
277	    /**
278	     * Rolls a date forward to the next business day: a Saturday or Sunday is advanced to the
279	     * following Monday, while a weekday is returned unchanged.
280	     *
281	     * @param date the date to adjust
282	     * @return the same date when it is a weekday, otherwise the next Monday
283	     */
284	    private LocalDate toBusinessDay(LocalDate date) {
285	        java.time.DayOfWeek day = date.getDayOfWeek();
286	        if (day == java.time.DayOfWeek.SATURDAY || day == java.time.DayOfWeek.SUNDAY) {
287	            return date.with(java.time.temporal.TemporalAdjusters.next(java.time.DayOfWeek.MONDAY));
288	        }
289	        return date;
290	    }
291	
292	    /**
293	     * The maximum number of owners that may be created on a single day. Once this many owners
294	     * already carry today's {@code registrationDate}, no further owner may be created today.
295	     */
296	    private static final long DAILY_OWNER_LIMIT = 100L;
297	
298	    /**
299	     * Rejects a new owner when {@link #DAILY_OWNER_LIMIT} or more owners already carry the given
300	     * adjusted business-day {@code registrationDate}. The count is taken against the same adjusted
301	     * date the new owner would be stored with, so owners are capped per business day. When the limit
302	     * has been reached a {@link DailyOwnerLimitExceededException} is thrown, which the exception
303	     * advice renders as a 429 Too Many Requests response.
304	     *
305	     * @param registrationDate the adjusted business-day registration date of the owner being created
306	     */
307	    private void rejectDailyLimitExceeded(LocalDate registrationDate) {
308	        long count = this.clinicService.findAllOwners().stream()
309	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
310	            .count();
311	        if (count >= DAILY_OWNER_LIMIT) {
312	            throw new DailyOwnerLimitExceededException(registrationDate);
313	        }
314	    }
315	
316	    /**
317	     * The number of owners that may carry a single day's {@code registrationDate} before that day
318	     * is flagged as a bulk-signup day. Once more than this many owners share a registration date,
319	     * the create and read responses report {@code bulkSignupWarning} true for that date.
320	     */
321	    private static final long BULK_SIGNUP_WARNING_THRESHOLD = 80L;
322	
323	    /**
324	     * Reports whether the given business-day {@code registrationDate} is a bulk-signup day, i.e.
325	     * whether more than {@link #BULK_SIGNUP_WARNING_THRESHOLD} owners already carry that date. The
326	     * count is taken against the same adjusted date owners are stored with, mirroring the
327	     * per-day create-limit accumulation. A {@code null} date is never a bulk-signup day.
328	     *
329	     * @param registrationDate the adjusted business-day registration date to test, or {@code null}
330	     * @return {@code true} when more than 80 owners share the date, otherwise {@code false}
331	     */
332	    private boolean bulkSignupWarning(LocalDate registrationDate) {
333	        if (registrationDate == null) {
334	            return false;
335	        }
336	        long count = this.clinicService.findAllOwners().stream()
337	            .filter(existing -> registrationDate.equals(existing.getRegistrationDate()))
338	            .count();
339	        return count > BULK_SIGNUP_WARNING_THRESHOLD;
340	    }
341	
342	    /**
343	     * The maximum number of owners a single city may hold. Once a city already contains this
344	     * many owners, no further owner may be created in it.
345	     */
346	    private static final long CITY_OWNER_CAPACITY = 50L;
347	
348	    /**
349	     * Rejects a new owner whose city already contains {@link #CITY_OWNER_CAPACITY} or more owners.
350	     * Cities are compared case-insensitively, consistent with how per-city owners are counted
351	     * elsewhere. When the city is at capacity a {@link CityCapacityExceededException} is thrown,
352	     * which the exception advice renders as a 409 Conflict response.
353	     *
354	     * @param city the city of the owner being created
355	     */
356	    private void rejectCityAtCapacity(String city) {
357	        long count = this.clinicService.findAllOwners().stream()
358	            .filter(existing -> city != null && city.equalsIgnoreCase(existing.getCity()))
359	            .count();
360	        if (count >= CITY_OWNER_CAPACITY) {
361	            throw new CityCapacityExceededException(city);
362	        }
363	    }
364	
365	    /**
366	     * Builds the customer code assigned to a newly created owner. The code is formatted as
367	     * {@code '<REGION>-<HASH8>'}, where {@code REGION} is the owner's canonical region (see
368	     * {@link Owner#getRegion()}), rendered {@code 'UNKNOWN'} when the owner has no known region,
369	     * and {@code HASH8} is the first 8 upper-case hex characters of the SHA-256 digest over the
370	     * owner's normalized E.164 {@code telephone} concatenated with its {@code lastName}. The code
371	     * carries no sequence number, so two owners sharing a region, telephone and last name resolve to
372	     * the same code. The whole owner is taken so the code is derived from whichever of its fields the
373	     * identity scheme needs.
374	     *
375	     * @param owner the owner being created, whose fields the code is derived from
376	     * @return the formatted customer code
377	     */
378	    private String customerCodeFor(Owner owner) {
379	        String region = owner.getRegion();
380	        String regionCode = region != null ? region : "UNKNOWN";
381	        String hash8 = shaHex(owner.getTelephone() + owner.getLastName(), 8);
382	        return regionCode + "-" + hash8;
383	    }
384	
385	    /**
386	     * Counts the existing owners that share the given {@code firstName} and {@code lastName}
387	     * with the owner being created, compared case-insensitively. The count is taken before the
388	     * new owner is persisted, so it reflects only pre-existing owners and never includes the new
389	     * owner itself. The resulting value is stored on the owner and exposed as {@code namesakeCount}.
390	     *
391	     * @param firstName the first name of the owner being created
392	     * @param lastName the last name of the owner being created
393	     * @return the number of pre-existing owners sharing the same first and last name
394	     */
395	    private int countNamesakes(String firstName, String lastName) {
396	        return (int) this.clinicService.findAllOwners().stream()
397	            .filter(existing -> firstName.equalsIgnoreCase(existing.getFirstName())
398	                && lastName.equalsIgnoreCase(existing.getLastName()))
399	            .count();
400	    }
401	
402	    /**
403	     * Flags a newly created owner as a possible (soft) duplicate. Reaching this point means the
404	     * owner already cleared {@link #rejectDuplicateIdentity(OwnerFieldsDto)}, so it is not a hard
405	     * household duplicate. A member that declared its household via {@code sharesHousehold} is a
406	     * deliberate addition to a known household, not a suspected duplicate, so it is never flagged.
407	     * Otherwise it is a possible duplicate when an existing owner shares its {@code lastName}
408	     * (compared case-insensitively) and its {@code postcode} while carrying a different (normalized)
409	     * {@code telephone}. When such an owner is found, {@code possibleDuplicate} is set {@code true}
410	     * and {@code possibleDuplicateOf} to the matching owner's id; otherwise {@code possibleDuplicate}
411	     * is set {@code false} and no matching id is recorded. An owner without a postcode can share no
412	     * postcode and is never a possible duplicate.
413	     *
414	     * @param owner the owner being created, already carrying its normalized telephone and postcode
415	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
416	     */
417	    private void applyPossibleDuplicate(Owner owner, OwnerFieldsDto ownerFieldsDto) {
418	        owner.setPossibleDuplicate(false);
419	        owner.setPossibleDuplicateOf(null);
420	        if (sharesHousehold(ownerFieldsDto)) {
421	            return;
422	        }
423	        findPossibleDuplicate(owner).ifPresent(existing -> {
424	            owner.setPossibleDuplicate(true);
425	            owner.setPossibleDuplicateOf(existing.getId());
426	        });
427	    }
428	
429	    /**
430	     * Finds the existing owner, if any, that makes the given newly created owner a possible (soft)
431	     * duplicate: an owner sharing its {@code lastName} (compared case-insensitively) and its
432	     * {@code postcode} while carrying a different (normalized) {@code telephone}. This is the single
433	     * definition of the soft-duplicate match; {@link #applyPossibleDuplicate(Owner, OwnerFieldsDto)} only records the
434	     * outcome on the owner. An owner without a postcode can share no postcode and matches nothing, so
435	     * {@link java.util.Optional#empty()} is returned.
436	     *
437	     * @param owner the owner being created, already carrying its normalized telephone and postcode
438	     * @return the matching existing owner, or {@link java.util.Optional#empty()} when none matches
439	     */
440	    private java.util.Optional<Owner> findPossibleDuplicate(Owner owner) {
441	        if (owner.getPostcode() == null) {
442	            return java.util.Optional.empty();
443	        }
444	        return this.clinicService.findAllOwners().stream()
445	            .filter(existing -> owner.getLastName().equalsIgnoreCase(existing.getLastName())
446	                && owner.getPostcode().equals(existing.getPostcode())
447	                && !owner.getTelephone().equals(existing.getTelephone()))
448	            .findFirst();
449	    }
450	
451	    /**
452	     * Rejects an owner whose {@code firstName}, {@code lastName}, {@code address}, {@code city}
453	     * or {@code telephone} is missing or blank. A field that is only whitespace is treated as
454	     * blank. When any field fails, a {@link RequiredFieldsMissingException} is thrown carrying
455	     * the names of every offending field, which the exception advice renders as a 400 response
456	     * with an {@code errors} array.
457	     *
458	     * @param ownerFieldsDto the submitted owner fields
459	     */
460	    private void validateRequiredFields(OwnerFieldsDto ownerFieldsDto) {
461	        List<String> missing = new ArrayList<>();
462	        addIfBlank(missing, "firstName", ownerFieldsDto.getFirstName());
463	        addIfBlank(missing, "lastName", ownerFieldsDto.getLastName());
464	        addIfBlank(missing, "address", ownerFieldsDto.getAddress());
465	        addIfBlank(missing, "city", ownerFieldsDto.getCity());
466	        addIfBlank(missing, "telephone", ownerFieldsDto.getTelephone());
467	        if (!missing.isEmpty()) {
468	            throw new RequiredFieldsMissingException(missing);
469	        }
470	    }
471	
472	    private void addIfBlank(List<String> missing, String fieldName, String value) {
473	        if (value == null || value.isBlank()) {
474	            missing.add(fieldName);
475	        }
476	    }
477	
478	    /**
479	     * Normalizes a submitted telephone number into E.164 form. Spaces, dashes and brackets
480	     * are stripped. When a leading {@code '+'} and country code are present they are kept as
481	     * given; otherwise the country code {@code '+61'} is assumed and a single leading
482	     * {@code '0'} is dropped from the national digits. The result must be a {@code '+'}
483	     * followed by 8 to 15 digits. The normalized E.164 value is what gets stored and returned.
484	     * When the value cannot form a valid E.164 number an {@link InvalidFieldsException} is
485	     * thrown, which the exception advice renders as a 400 response naming the {@code telephone}
486	     * field. For example {@code "0412 345 678"} becomes {@code "+61412345678"}.
487	     *
488	     * @param telephone the submitted telephone value
489	     * @return the normalized E.164 telephone
490	     */
491	    private String normalizeTelephone(String telephone) {
492	        String cleaned = telephone == null ? "" : telephone.replaceAll("[\\s\\-()]", "");
493	        String e164;
494	        if (cleaned.startsWith("+")) {
495	            e164 = "+" + cleaned.substring(1);
496	        } else {
497	            String national = cleaned;
498	            if (national.startsWith("0")) {
499	                national = national.substring(1);
500	            }
501	            e164 = "+61" + national;
502	        }
503	        if (!e164.matches("^\\+[0-9]{8,15}$")) {
504	            throw new InvalidFieldsException(List.of("telephone"));
505	        }
506	        validateNationalNumberLength(e164);
507	        return e164;
508	    }
509	
510	    /**
511	     * Validates the national-number length of an already syntactically valid E.164 telephone
512	     * against its country code. When the number carries a country code this application recognizes
513	     * (see {@link Owner#countryCodeOf(String)}) the digits following that code must have exactly the
514	     * length that code admits ({@code '+61'} => 9 national digits, {@code '+1'} => 10, see
515	     * {@link Owner#nationalNumberLength(String)}). When the country code is recognized but the
516	     * national number is the wrong length an {@link InvalidFieldsException} is thrown, which the
517	     * exception advice renders as a 400 response naming the {@code telephone} field. A country code
518	     * that is not recognized carries no per-country length rule and is left to the general
519	     * 8-to-15-digit E.164 check.
520	     *
521	     * @param e164 the normalized E.164 telephone (a {@code '+'} followed by digits)
522	     */
523	    private void validateNationalNumberLength(String e164) {
524	        String countryCode = Owner.countryCodeOf(e164);
525	        if (countryCode == null) {
526	            return;
527	        }
528	        int nationalLength = e164.length() - 1 - countryCode.length();
529	        if (nationalLength != Owner.nationalNumberLength(countryCode)) {
530	            throw new InvalidFieldsException(List.of("telephone"));
531	        }
532	    }
533	
534	    /**
535	     * Pattern for a syntactically valid email address: a non-empty local part, an {@code @},
536	     * and a domain containing at least one dot, none of the parts holding whitespace or a
537	     * second {@code @}.
538	     */
539	    private static final java.util.regex.Pattern EMAIL_PATTERN =
540	        java.util.regex.Pattern.compile("^[^\\s@]+@[^\\s@]+\\.[^\\s@]+$");
541	
542	    /**
543	     * Disposable email domains an owner may not register with. An email whose domain (compared
544	     * case-insensitively) is one of these is rejected, since it identifies a throwaway mailbox.
545	     */
546	    private static final java.util.Set<String> DISPOSABLE_EMAIL_DOMAINS =
547	        java.util.Set.of("mailinator.com", "tempmail.com", "guerrillamail.com");
548	
549	    /**
550	     * Normalizes an optional owner email. An email is optional, so a {@code null} value is
551	     * accepted and returned unchanged. When present it must be a syntactically valid address
552	     * whose domain is not on the disposable-domain blocklist (see
553	     * {@link #DISPOSABLE_EMAIL_DOMAINS}); the value is stored and returned lower-cased. When
554	     * present but syntactically invalid or on a disposable domain an
555	     * {@link InvalidFieldsException} is thrown, which the exception advice renders as a 400
556	     * response naming the {@code email} field.
557	     *
558	     * @param email the submitted email value, or {@code null} when omitted
559	     * @return the lower-cased email, or {@code null} when none was supplied
560	     */
561	    private String normalizeEmail(String email) {
562	        if (email == null) {
563	            return null;
564	        }
565	        String trimmed = email.trim();
566	        if (!EMAIL_PATTERN.matcher(trimmed).matches()) {
567	            throw new InvalidFieldsException(List.of("email"));
568	        }
569	        String domain = trimmed.substring(trimmed.lastIndexOf('@') + 1).toLowerCase(java.util.Locale.ROOT);
570	        if (DISPOSABLE_EMAIL_DOMAINS.contains(domain)) {
571	            throw new InvalidFieldsException(List.of("email"));
572	        }
573	        return canonicalEmail(trimmed);
574	    }
575	
576	    /**
577	     * Reduces an email to the canonical form used both to store it and to compare it against
578	     * other owners' emails: surrounding whitespace is trimmed and the value is lower-cased. A
579	     * {@code null} email (none was supplied) canonicalizes to {@code null}. Unlike
580	     * {@link #normalizeEmail(String)} no validation is performed, so this can be applied to a
581	     * value read back off an existing owner without risk of rejecting it. This is the single
582	     * definition of email identity: two emails denote the same address exactly when they
583	     * canonicalize to the same value, so an email stored via {@link #normalizeEmail(String)} and
584	     * an email already on an existing owner can be compared for equality after both pass through
585	     * here. For example {@code "  Jane@Example.COM "} canonicalizes to {@code "jane@example.com"}.
586	     *
587	     * @param email the email to canonicalize, or {@code null} when none was supplied
588	     * @return the trimmed, lower-cased email, or {@code null} when {@code email} is {@code null}
589	     */
590	    private String canonicalEmail(String email) {
591	        if (email == null) {
592	            return null;
593	        }
594	        return email.trim().toLowerCase(java.util.Locale.ROOT);
595	    }
596	
597	    /**
598	     * Validates an optional owner postcode. A postcode is optional, so a {@code null} value is
599	     * accepted and left unchanged. When present it must be exactly 4 digits, and when the owner's
600	     * city has a known region (see {@link Owner#regionForCity(String)}) the postcode must fall
601	     * within that region's inclusive range ({@code NSW 2000-2099}, {@code VIC 3000-3099},
602	     * {@code QLD 4000-4099}, see {@link Owner#postcodeRangeForRegion(String)}). A city with no known
603	     * region admits any 4-digit postcode. When present but malformed or out of range for the city's
604	     * region an {@link InvalidFieldsException} is thrown, which the exception advice renders as a
605	     * 400 response naming the {@code postcode} field.
606	     *
607	     * @param postcode the submitted postcode, or {@code null} when omitted
608	     * @param city the owner's city, used to resolve the region whose range the postcode must satisfy
609	     */
610	    private void validatePostcode(String postcode, String city) {
611	        if (postcode == null) {
612	            return;
613	        }
614	        if (!postcode.matches("^[0-9]{4}$")) {
615	            throw new InvalidFieldsException(List.of("postcode"));
616	        }
617	        int[] range = Owner.postcodeRangeForRegion(Owner.regionForCity(city));
618	        if (range != null) {
619	            int value = Integer.parseInt(postcode);
620	            if (value < range[0] || value > range[1]) {
621	                throw new InvalidFieldsException(List.of("postcode"));
622	            }
623	        }
624	    }
625	
626	    /**
627	     * Rejects a new owner that would join a household already occupied by an existing owner. The
628	     * household is keyed on {@code (lastName, postcode)} and identified by the deterministic
629	     * {@code householdId} the owner would receive (see {@link #householdIdFor(String, String)}), so
630	     * two owners sharing a last name and postcode belong to the same household. When any existing
631	     * owner already carries that household identifier the new owner is a household duplicate and a
632	     * {@link DuplicateIdentityException} is thrown, which the exception advice renders as a 409
633	     * Conflict response. Setting {@code sharesHousehold} declares the owner a deliberate member of
634	     * that household and bypasses this block, so it is created rather than rejected. An owner without
635	     * a postcode belongs to no shared household and is never a household duplicate.
636	     *
637	     * @param ownerFieldsDto the submitted owner fields, already normalized in place
638	     */
639	    private void rejectDuplicateIdentity(OwnerFieldsDto ownerFieldsDto) {
640	        if (sharesHousehold(ownerFieldsDto)) {
641	            return;
642	        }
643	        String householdId = householdIdFor(ownerFieldsDto.getLastName(), ownerFieldsDto.getPostcode());
644	        if (householdId == null) {
645	            return;
646	        }
647	        boolean taken = this.clinicService.findAllOwners().stream()
648	            .anyMatch(existing -> householdId.equals(existing.getHouseholdId()));
649	        if (taken) {
650	            throw new DuplicateIdentityException(householdId);
651	        }
652	    }
653	
654	    /**
655	     * Assigns the deterministic shared {@code householdId} to a newly created owner. The identifier
656	     * is derived from the owner's household identity — its {@code lastName} and {@code postcode} (see
657	     * {@link #householdIdFor(String, String)}) — so every owner sharing a last name and postcode
658	     * resolves to the same stable value automatically, without any explicit linking. An owner without
659	     * a postcode belongs to no shared household and is left without a household identifier.
660	     *
661	     * @param owner the newly created owner, mutated in place with its household identifier
662	     */
663	    private void assignHousehold(Owner owner) {
664	        owner.setHouseholdId(householdIdFor(owner.getLastName(), owner.getPostcode()));
665	    }
666	
667	    /**
668	     * Reports whether a submitted owner opted into sharing a household, i.e. whether its request
669	     * carried {@code sharesHousehold} set to {@code true}. A {@code null} or {@code false} flag is
670	     * not opting in. This is the single reading of the {@code sharesHousehold} intent, shared by
671	     * every rule that treats a declared household member differently from an independent owner.
672	     *
673	     * @param ownerFieldsDto the submitted owner fields carrying the {@code sharesHousehold} flag
674	     * @return {@code true} when the request opted into sharing a household
675	     */
676	    private boolean sharesHousehold(OwnerFieldsDto ownerFieldsDto) {
677	        return Boolean.TRUE.equals(ownerFieldsDto.getSharesHousehold());
678	    }
679	
680	    /**
681	     * Derives the stable {@code householdId} shared by every owner in the household identified by
682	     * the given {@code lastName} and {@code postcode}. The household is keyed on {@code (lastName,
683	     * postcode)}: the normalized last name and the postcode are hashed with SHA-256 and the leading
684	     * 12 hex characters of the digest form the identifier, so any two owners sharing a last name and
685	     * postcode — regardless of creation order or address — resolve to the same identifier
686	     * automatically. An owner without a postcode belongs to no shared household, so {@code null} is
687	     * returned.
688	     *
689	     * @param lastName the household's last name
690	     * @param postcode the household's postcode, or {@code null} when the owner has none
691	     * @return the deterministic household identifier, or {@code null} when {@code postcode} is {@code null}
692	     */
693	    private String householdIdFor(String lastName, String postcode) {
694	        if (postcode == null) {
695	            return null;
696	        }
697	        return shaHex(householdKey(lastName, postcode), 12);
698	    }
699	
700	    /**
701	     * Builds the canonical household key that identifies the household a {@code lastName} and
702	     * {@code postcode} belong to: the normalized last name (case-insensitive, with collapsed
703	     * whitespace) joined to the postcode by {@code '|'}. This is the single definition of which
704	     * owner fields make up a household and how they are normalized;
705	     * {@link #householdIdFor(String, String)} hashes this key into the stored identifier, so any two
706	     * owners in the same household resolve to the same key and therefore the same identifier.
707	     *
708	     * @param lastName the household's last name
709	     * @param postcode the household's postcode
710	     * @return the normalized household key
711	     */
712	    private String householdKey(String lastName, String postcode) {
713	        return collapseWhitespace(lastName).toLowerCase(java.util.Locale.ROOT) + "|" + postcode;
714	    }
715	
716	    /**
717	     * Computes the upper-case hex SHA-256 digest of a string, truncated to its first
718	     * {@code hexChars} characters. The input is hashed as UTF-8 bytes and each digest byte is
719	     * rendered as two upper-case hex digits, so {@code hexChars} characters cover the leading
720	     * {@code ceil(hexChars / 2)} bytes of the digest. This is the single definition of the
721	     * SHA-256 hex derivation shared by every rule that hashes owner fields (for example the
722	     * household identifier). SHA-256 is a required platform algorithm; were it ever unavailable
723	     * an {@link IllegalStateException} is thrown.
724	     *
725	     * @param input the string to hash
726	     * @param hexChars the number of leading upper-case hex characters to return
727	     * @return the first {@code hexChars} upper-case hex characters of the SHA-256 digest
728	     */
729	    private String shaHex(String input, int hexChars) {
730	        try {
731	            byte[] digest = java.security.MessageDigest.getInstance("SHA-256")
732	                .digest(input.getBytes(java.nio.charset.StandardCharsets.UTF_8));
733	            StringBuilder sb = new StringBuilder();
734	            for (int i = 0; i < digest.length && sb.length() < hexChars; i++) {
735	                sb.append(String.format("%02X", digest[i]));
736	            }
737	            return sb.substring(0, hexChars);
738	        }
739	        catch (java.security.NoSuchAlgorithmException e) {
740	            throw new IllegalStateException("SHA-256 is required but unavailable", e);
741	        }
742	    }
743	
744	    /**
745	     * Counts the owners that belong to the household identified by the given {@code householdId},
746	     * i.e. every owner carrying that exact identifier. The count is taken against the current set
747	     * of owners, so after a create it reflects the household's size including the newly persisted
748	     * owner. An owner without a household (a {@code null} identifier) belongs to no shared
749	     * household and yields {@code 0}.
750	     *
751	     * @param householdId the shared household identifier, or {@code null} when the owner shares no household
752	     * @return the number of owners in the household, or {@code 0} when {@code householdId} is {@code null}
753	     */
754	    private int countHouseholdMembers(String householdId) {
755	        if (householdId == null) {
756	            return 0;
757	        }
758	        return (int) this.clinicService.findAllOwners().stream()
759	            .filter(existing -> householdId.equals(existing.getHouseholdId()))
760	            .count();
761	    }
762	
763	    /**
764	     * Collapses a field for household comparison: leading and trailing whitespace is trimmed and
765	     * every internal run of whitespace is reduced to a single space. A {@code null} value collapses
766	     * to the empty string. Case is left untouched so callers can compare case-insensitively.
767	     *
768	     * @param value the value to collapse, or {@code null}
769	     * @return the whitespace-collapsed value, never {@code null}
770	     */
771	    private String collapseWhitespace(String value) {
772	        if (value == null) {
773	            return "";
774	        }
775	        return value.trim().replaceAll("\\s+", " ");
776	    }
777	
778	    /**
779	     * Common street-type abbreviations expanded during address normalization, keyed by their
780	     * upper-cased token.
781	     */
782	    private static final java.util.Map<String, String> ADDRESS_ABBREVIATIONS =
783	        java.util.Map.of("ST", "STREET", "RD", "ROAD", "AVE", "AVENUE");
784	
785	    /**
786	     * Normalizes a submitted address into the canonical form stored and returned for an owner:
787	     * leading and trailing whitespace is trimmed, every internal run of whitespace is collapsed to
788	     * a single space, the value is upper-cased, and common street-type abbreviations are expanded
789	     * ({@code ST -> STREET}, {@code RD -> ROAD}, {@code AVE -> AVENUE}). A {@code null} value
790	     * normalizes to the empty string, and an address that holds only whitespace normalizes to the
791	     * empty string so the required-field check rejects it. For example {@code "  12  main  st "}
792	     * becomes {@code "12 MAIN STREET"}. This is the single definition of address normalization used
793	     * everywhere an address is stored or compared.
794	     *
795	     * @param address the submitted address value, or {@code null}
796	     * @return the normalized address, never {@code null}
797	     */
798	    private String normalizeAddress(String address) {
799	        if (address == null) {
800	            return "";
801	        }
802	        String collapsed = address.trim().replaceAll("\\s+", " ").toUpperCase(java.util.Locale.ROOT);
803	        if (collapsed.isEmpty()) {
804	            return "";
805	        }
806	        String[] tokens = collapsed.split(" ");
807	        StringBuilder sb = new StringBuilder(collapsed.length());
808	        for (int i = 0; i < tokens.length; i++) {
809	            if (i > 0) {
810	                sb.append(' ');
811	            }
812	            sb.append(ADDRESS_ABBREVIATIONS.getOrDefault(tokens[i], tokens[i]));
813	        }
814	        return sb.toString();
815	    }
816	}
